predictions.prediction_sql:
SELECT T1.District, T1.County, T1.School, COALESCE(T1.AdmLName1, 'Unknown') AS AdmLName1
FROM schools AS T1
WHERE T1.CharterNum = '40';

SELECT CAST((MIN(milliseconds) - MAX(milliseconds)) AS REAL) * 100 / MIN(milliseconds)
FROM results
WHERE raceId = (SELECT raceId FROM races WHERE year = 2008 AND name = 'Australian Grand Prix');
